/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-hover-card {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-label-size, 13px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.5);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.015em);
  color: var(--ui-text, #171717);
  overflow-wrap: anywhere;
  --ui-navigation-height: var(--ui-control-height-md, 40px);
  --ui-navigation-padding: var(--ui-control-padding-x-md, 14px);
  --ui-navigation-icon: var(--ui-icon-size-md, 16px);
  --ui-navigation-close-size: var(--ui-control-height-sm, 32px);
}
:where([data-moru-registry]) [data-size='sm'].ui-hover-card {
  --ui-navigation-height: var(--ui-control-height-sm, 32px);
  --ui-navigation-padding: var(--ui-control-padding-x-sm, 10px);
  --ui-navigation-icon: var(--ui-icon-size-sm, 14px);
  font-size: var(--ui-type-caption-size, 12px);
}
:where([data-moru-registry]) [data-size='lg'].ui-hover-card {
  --ui-navigation-height: var(--ui-control-height-lg, 48px);
  --ui-navigation-padding: var(--ui-control-padding-x-lg, 18px);
  --ui-navigation-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-hover-card {
  max-width: min(calc(100vw - 24px), var(--available-width, calc(100vw - 24px)));
  max-height: min(calc(100dvh - 24px), var(--available-height, calc(100dvh - 24px)));
  overflow-y: auto;
  overscroll-behavior: contain;
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 8px 28px #00000016);
  transform-origin: var(--transform-origin);
  transition:
    opacity var(--ui-duration, 160ms),
    transform var(--ui-duration, 160ms);
}
:where([data-moru-registry]) .ui-hover-card[data-starting-style],
:where([data-moru-registry]) .ui-hover-card[data-ending-style] {
  opacity: 0;
  transform: scale(0.97);
}
:where([data-moru-registry]) .ui-hover-card {
  width: 304px;
  padding: var(--ui-navigation-padding);
}
:where([data-moru-registry]) .ui-hover-card h3 {
  margin: 0;
  font: inherit;
}
:where([data-moru-registry]) .ui-hover-card p {
  margin: var(--ui-field-gap, 8px) 0 0;
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-caption-weight, 400);
  line-height: var(--ui-type-caption-line-height, 1.5);
}
:where([data-moru-registry]) .ui-hover-card-content {
  margin-top: var(--ui-form-gap, 20px);
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-hover-card {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useId, useState, type ReactElement, type ReactNode } from 'react'
import { PreviewCard as BasePreviewCard } from '@base-ui/react/preview-card'
import { cn } from './_lib/cn'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './navigation-shared.css'
import './hover-card.css'

export interface HoverCardProps {
  trigger: ReactElement
  title: string
  description?: string
  children?: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  size?: 'sm' | 'md' | 'lg'
  side?: 'top' | 'bottom' | 'left' | 'right'
  delay?: number
  className?: string
}
export function HoverCard({
  trigger,
  title,
  description,
  children,
  open,
  defaultOpen = false,
  onOpenChange,
  disabled,
  size = 'md',
  side = 'bottom',
  delay = 250,
  className,
}: HoverCardProps) {
  const portalContainer = useThemePortalContainer()
  const titleId = useId()
  const descriptionId = useId()
  const popupId = useId()
  const [localOpen, setLocalOpen] = useState(defaultOpen)
  const shown = !disabled && (open ?? localOpen)
  const existingDescription = (trigger.props as { 'aria-describedby'?: string })['aria-describedby']
  const describedBy =
    [existingDescription, shown ? popupId : undefined].filter(Boolean).join(' ') || undefined
  return (
    <BasePreviewCard.Root
      open={shown}
      onOpenChange={(next, details) => {
        if (disabled && next) {
          details.cancel()
          return
        }
        if (open === undefined) setLocalOpen(next)
        onOpenChange?.(next)
      }}
    >
      <BasePreviewCard.Trigger
        render={trigger}
        delay={delay}
        closeDelay={150}
        aria-describedby={describedBy}
        aria-expanded={shown}
        aria-controls={shown ? popupId : undefined}
        aria-disabled={disabled || undefined}
        tabIndex={disabled ? -1 : undefined}
        onClick={(event) => {
          if (disabled) event.preventDefault()
        }}
      />
      <OverlayPortal portal={BasePreviewCard.Portal} kind="menu" container={portalContainer}>
        <BasePreviewCard.Positioner
          className="ui-navigation-positioner"
          side={side}
          align="start"
          sideOffset={8}
          collisionPadding={12}
        >
          <BasePreviewCard.Popup
            id={popupId}
            role="group"
            className={cn('ui-hover-card', className)}
            data-size={size}
            aria-labelledby={titleId}
            aria-describedby={description ? descriptionId : undefined}
          >
            <h3 id={titleId}>{title}</h3>
            {description ? <p id={descriptionId}>{description}</p> : null}
            {children ? <div className="ui-hover-card-content">{children}</div> : null}
          </BasePreviewCard.Popup>
        </BasePreviewCard.Positioner>
      </OverlayPortal>
    </BasePreviewCard.Root>
  )
}
